CREATE TABLE IF NOT EXISTS "product" (
    "id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "slug" VARCHAR(255) NOT NULL UNIQUE,
    "name" VARCHAR(255) NOT NULL,
    "description" TEXT,
    "price" DECIMAL NOT NULL CHECK ("price" >= 0),
    "active" BOOLEAN NOT NULL,
    "stock" INTEGER CHECK ("stock" >= 0),
    PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "product_image" (
    "id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "product_id" INTEGER NOT NULL,
    "position" INTEGER,
    "link" VARCHAR(255) NOT NULL,
    PRIMARY KEY ("id")
);

CREATE TYPE order_status AS ENUM ('en attente', 'payée', 'traitée');

CREATE TABLE IF NOT EXISTS "order" (
    "id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "order_product_id" INTEGER NOT NULL,
    "email" VARCHAR(255) NOT NULL,
    "address" VARCHAR(255) NOT NULL,
    "city" VARCHAR(255) NOT NULL,
    "zip" INTEGER NOT NULL,
    "ref" INTEGER NOT NULL,
    "date" DATE NOT NULL,
    "total" DECIMAL NOT NULL,
    "status" order_status NOT NULL DEFAULT 'en attente',
    "shipping_offer_name" VARCHAR(255) NOT NULL,
    "shipping_offer_price" DECIMAL NOT NULL,
    "tracking_number" INTEGER,
    "shipping_company" VARCHAR(255) NOT NULL,
    PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "order_product" (
    "id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "order_id" INTEGER NOT NULL,
    "product_id" INTEGER NOT NULL,
    "quantity" INTEGER NOT NULL,
    "paid_price" DECIMAL,
    PRIMARY KEY ("id")
);

CREATE TYPE payment_status AS ENUM ('en attente', 'réussi', 'échoué');

CREATE TABLE IF NOT EXISTS "payment" (
    "id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "order_id" INTEGER NOT NULL,
    "stripe_ref" INTEGER NOT NULL,
    "amount" DECIMAL NOT NULL,
    "currency" VARCHAR(255) NOT NULL,
    "status" payment_status NOT NULL DEFAULT 'en attente',
    PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "shipping_company" (
    "id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "offer_id" INTEGER,
    "name" VARCHAR(255) NOT NULL,
    PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "shipping_company_offer" (
    "id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "name" VARCHAR(255) NOT NULL,
    "price" DECIMAL NOT NULL,
    PRIMARY KEY ("id")
);

ALTER TABLE "order" ENABLE ROW LEVEL SECURITY;

ALTER TABLE "product_image"
ADD FOREIGN KEY ("product_id") REFERENCES "product" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION;

ALTER TABLE "order_product"
ADD FOREIGN KEY ("order_id") REFERENCES "order" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION;

ALTER TABLE "order_product"
ADD FOREIGN KEY ("product_id") REFERENCES "product" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION;

ALTER TABLE "payment"
ADD FOREIGN KEY ("order_id") REFERENCES "order" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION;

ALTER TABLE "shipping_company_offer"
ADD FOREIGN KEY ("offer_id") REFERENCES "shipping_offer" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION;